import {sources,materials,groups,initialState} from './data.js';
const KEY='molis-onboarding-demo-v1';
let state=initialState();
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved?.version===1)state={...state,...saved,active:null};}catch{}
const app=document.getElementById('app'),modal=document.getElementById('modal');
let timer=null,toastTimer=null,editingName=null,editingSummary=false,connecting=null,opener=null;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<i data-lucide="${name}" class="icon ${cls}" aria-hidden="true"></i>`;
const srcIcon=s=>s.image?`<img src="/assets/${s.image}.svg" alt="">`:icon(s.icon);
const persist=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));}catch{}};
const available=s=>s.ready||state.connected.includes(s.id);
const picked=()=>sources.filter(s=>state.selected.includes(s.id));
function scoped(id){return materials.filter(m=>m.source===id).filter(m=>{
 if((id==='mail'||id==='chat')&&state.days===7&&m.date<'2026-09-18')return false;
 if(state.scope[id]==='focused'&&((id==='files'&&m.group!=='launch')||(id==='projects'&&m.id!=='p1')||(id==='browser'&&m.id!=='b1')))return false;
 return true;
});}
const readMaterials=()=>state.done.flatMap(id=>scoped(id));
const resultGroups=()=>Object.keys(groups).filter(g=>readMaterials().some(m=>m.group===g));
const byId=id=>materials.find(m=>m.id===id);
function scopeLabel(s){if(s.id==='mail')return `工作邮箱 · 最近 ${state.days} 天`;if(s.id==='chat')return `工作会话 · 最近 ${state.days} 天`;if(state.scope[s.id]==='focused')return {files:'文档 / 秋季发布',projects:'Projects / 官网改版 / 发布清单',browser:'当前标签页'}[s.id];return s.detail;}
function header(){return `<header class="topbar"><a class="brand" href="#" data-action="home"><span class="brand-mark">${icon('boxes')}</span>Molis Work</a><div class="top-actions"><span class="demo-label">交互原型<span> · 演示数据</span></span><button class="icon-btn" data-action="theme" aria-label="切换浅色或深色主题">${icon(document.documentElement.dataset.theme==='dark'?'sun':'moon')}</button><button class="icon-btn" data-action="reset" aria-label="重置演示">${icon('rotate-ccw')}</button></div></header>`;}
function intro(step){const isReading=step===1;return `<aside class="intro"><h1>${isReading?'让零散的内容，<br>慢慢连起来。':state.importTarget?'为这个项目，<br>补上已有材料。':state.newProject?'把已有资料，<br>变成一个新项目。':'从你正在做的事<br>开始。'}</h1><p>${isReading?'Molis 正在阅读选中的材料，整理共同主题、已有进展和接下来要处理的事。':'带上文件、网页和工作往来，Molis 帮你整理背景、进展与下一步。'}</p><ol class="step-list">${['带入内容','整理脉络','开始工作'].map((s,i)=>`<li class="${i===step?'current':i<step?'done':''}"><span class="step-dot">${i<step?icon('check'):i+1}</span>${s}</li>`).join('')}</ol><div class="intro-note">${icon('shield-check')}<span>${isReading?'每个判断都保留来源。<br>没有读到的内容，会明确告诉你。':'只读取清单中选中的范围。<br>原文件与消息保持原样。'}</span></div>${state.newProject?`<button class="text-button back-link" data-action="back-project">${icon('arrow-left')}回到原项目</button>`:''}</aside>`;}
function scopeUI(s){return `<div class="scope" id="scope-${s.id}"><div class="scope-inner">${s.scope==='time'?`<label for="days-${s.id}">读取时间<select id="days-${s.id}" data-days><option value="30" ${state.days===30?'selected':''}>最近 30 天</option><option value="7" ${state.days===7?'selected':''}>最近 7 天</option></select></label><p>时间设置同时应用于邮件和聊天。邮件不含附件，聊天保留所选会话上下文。</p>`:`<label for="range-${s.id}">内容范围<select id="range-${s.id}" data-range="${s.id}"><option value="all" ${state.scope[s.id]==='all'?'selected':''}>${s.id==='browser'?'标签页与书签':'全部所列资料'}</option><option value="focused" ${state.scope[s.id]==='focused'?'selected':''}>${{files:'只读秋季发布',projects:'只读发布清单',browser:'只读当前标签页'}[s.id]}</option></select></label><p>${s.id==='files'?'文档 / 秋季发布；文档 / 客户方案。':s.id==='projects'?'Projects / 官网改版。隐藏配置与依赖目录不读取。':'书签只用来定位网页，读取成功的正文才参与总结。'}</p>`}</div></div>`;}
function sourcesView(){return `<main class="arrival animate-content">${intro(0)}<div><section class="source-panel ${state.selected.length?'':'empty-choice'}" aria-label="选择材料来源"><div class="panel-head"><h2>想带入哪些内容？</h2><label class="select-all"><input class="check" id="select-all" type="checkbox" ${state.selected.length===sources.length?'checked':''}>全选</label></div><div>${sources.map(s=>`<article class="source ${state.selected.includes(s.id)?'selected':''}"><div class="source-main"><label class="source-hit" for="select-${s.id}"><input id="select-${s.id}" class="check" type="checkbox" data-select="${s.id}" ${state.selected.includes(s.id)?'checked':''}><span class="source-icon ${s.tone}">${srcIcon(s)}</span><span class="source-copy"><span class="source-title">${s.name}<span class="source-status ${available(s)?'ready':''}">${available(s)?icon('check')+'可读取':'需连接'}</span></span><p>${esc(scopeLabel(s))}</p></span></label>${!available(s)?`<button class="btn secondary small source-connect" data-connect="${s.id}">连接 ${s.id==='mail'?'Google':s.name}${icon('arrow-up-right')}</button>`:''}<button class="scope-toggle" id="toggle-${s.id}" data-scope="${s.id}" aria-label="调整${s.name}范围" aria-expanded="${state.expanded===s.id}" aria-controls="scope-${s.id}">${icon('chevron-down')}</button></div>${state.expanded===s.id?scopeUI(s):''}</article>`).join('')}</div><footer class="source-footer"><div class="selection-recap"><span><b>${state.selected.length?'已选 '+state.selected.length+' 个来源':'选择内容即可开始'}</b></span><span class="model-note">${icon('sparkles')}演示模型 · 本次整理</span></div><div class="footer-actions"><button class="text-button" data-action="new-project">空白开始${icon('arrow-up-right')}</button><button class="btn primary" id="start" data-action="start" ${!state.selected.length?'disabled':''}>开始整理${icon('arrow-right')}</button></div></footer></section><p class="subfoot">所选正文将交给模型整理。<button data-action="privacy">了解读取范围</button></p></div></main>`;}
function readingView(){const ps=picked(),count=state.done.length+state.skipped.length,waiting=ps.filter(s=>!available(s)&&!state.skipped.includes(s.id));const next=waiting[0];const failed=next&&state.failed.includes(next.id);return `<main class="arrival animate-content">${intro(1)}<section class="source-panel" aria-label="材料整理进度"><div class="reading-head"><div class="heading-line"><h2>${state.done.length?'正在整理工作脉络':'正在读入你的材料'}</h2><span class="muted"><small>${count} / ${ps.length}</small></span></div><p>${state.done.length?`已读取 ${readMaterials().length} 份材料，保留每份内容的来源。`:'从已就绪的来源开始，其他连接可以随后补齐。'}</p><div class="progress-track" role="progressbar" aria-label="来源处理进度" aria-valuemin="0" aria-valuemax="${ps.length}" aria-valuenow="${count}"><div class="progress-fill" style="transform:scaleX(${ps.length?count/ps.length:0})"></div></div></div>${ps.map(s=>{const done=state.done.includes(s.id),skip=state.skipped.includes(s.id),active=state.active===s.id,fail=state.failed.includes(s.id);return `<div class="receipt"><span class="source-icon ${s.tone}">${srcIcon(s)}</span><div class="receipt-copy">${s.name}<p>${done?`${scoped(s.id).length} 份材料 · 原始来源已保留`:skip?'本次未读取':scopeLabel(s)}</p></div><span class="receipt-state ${done?'done':fail?'failed':active?'active':''}">${icon(done?'check':skip?'minus':fail?'circle-alert':active?'loader-circle':'clock-3',active?'spinner':'')}${done?'已读取':skip?'已跳过':fail?'连接失败':active?'读取中':available(s)?'等待读取':'待连接'}</span></div>`;}).join('')}${next?`<section class="connection" aria-label="连接所选账号"><div class="connection-top">${srcIcon(next)}<h3>${failed?'重新连接':'连接'} ${next.name}</h3></div><p class="${failed?'error-copy':''}">${failed?'这次连接没有完成。可以重试，也可以先整理其他材料。':`连接后继续读取最近 ${state.days} 天的${next.id==='mail'?'邮件正文与线程':'会话记录'}。已经就绪的来源会继续整理。`}</p><div class="connection-actions"><button class="btn primary small" data-connect="${next.id}" ${connecting?'disabled':''}>${connecting===next.id?'连接中…':failed?'重试连接':'连接 '+next.name}${icon('arrow-up-right')}</button><button class="btn quiet small" data-skip="${next.id}" ${connecting?'disabled':''}>本次跳过</button></div><p class="demo-hint">此处演示连接，不访问真实账号。<button class="text-button" data-fail="${next.id}">体验连接失败</button></p></section>`:''}<div class="reading-footer"><span class="receipt-totals">${state.skipped.length?state.skipped.length+' 个来源未纳入':'可以离开，回来后接着整理'}</span><button class="btn secondary small" data-action="finish-partial" ${!state.done.length?'disabled':''}>先看已整理的内容${icon('arrow-right')}</button></div></section></main>`;}
function factsFor(docs){let ordered=[...docs];if(docs.some(d=>d.id==='m1')&&docs.some(d=>d.id==='f1')){ordered=docs.filter(d=>!['f1','m1'].includes(d.id));return [{text:'发布简报写的是 10 月 1 日；9 月 23 日的邮件将日期调整为 10 月 8 日，相关材料需要核对。',refs:['f1','m1']},...ordered.slice(0,2).map(m=>({text:m.fact,refs:[m.id]}))];}return ordered.slice(0,3).map(m=>({text:m.fact,refs:[m.id]}));}
function nextFor(group,docs){if(!group)return '核对整理出的背景与进展，选一件事开始推进。';if(group==='launch'){if(docs.some(m=>m.id==='m1')&&docs.some(m=>m.id==='f1'))return '先核对最终发布日期，再统一发布材料中的时间。';if(docs.some(m=>['p1','c1'].includes(m.id)))return '核对新版截图与移动端检查的最新进展。';return '补充最新发布排期，整理仍待确认的准备事项。';}return docs.some(m=>m.id==='c2')?'把“从结论回到原文”的演示要求补进方案。':'核对试点范围，补充下一次沟通需要展示的内容。';}
const citations=(ids,docs)=>ids.map(id=>`<button class="citation" data-cite="${id}" aria-label="查看来源：${esc(byId(id).title)}">${docs.findIndex(d=>d.id===id)+1}</button>`).join('');
function factHTML(docs){return factsFor(docs).map(f=>`<div class="fact-row"><span>${esc(f.text)}${citations(f.refs,docs)}</span></div>`).join('');}
function reviewView(){const docs=readMaterials(),gs=resultGroups();if(!gs.length)return `<main class="review-page"><section class="source-panel empty-result">${icon('folder-open')}<h2>还没有可整理的内容</h2><p>所选来源暂未读入材料。保留了你的选择，可以连接后继续。</p><button class="btn primary" data-action="back-sources">回到来源清单</button></section></main>`;return `<main class="review-page animate-content"><div class="review-top"><span class="success-line">${icon('check-circle-2')}第一份工作脉络，已经整理好了</span><button class="text-button" data-action="back-sources">${icon('plus')}补充来源</button></div><div class="review-title"><h1>这些内容，正在围绕 ${gs.length} 件事展开。</h1><p>这是 Molis 对所选材料的理解。调整一下，就可以接着做。</p></div><div class="coverage"><span>${icon('files')}${docs.length} 份材料</span><span>${icon('layers-2')}${state.done.length} 个来源</span><span>${icon('clock-3')}截至 2026 年 9 月 24 日</span>${state.skipped.length?`<span class="incomplete">${icon('circle-alert')}${state.skipped.map(id=>sources.find(s=>s.id===id).name).join('、')}未读取</span>`:''}</div><div class="review-layout"><section aria-label="项目建议">${gs.map(g=>{const d=docs.filter(m=>m.group===g),meta=groups[g];return `<article class="project-proposal"><header class="proposal-header"><input class="check" id="adopt-${g}" data-adopt="${g}" type="checkbox" aria-label="采用${esc(state.names[g])}" ${state.adopt.includes(g)?'checked':''}>${icon(meta.icon,meta.tone)}<div class="proposal-heading">${editingName===g?`<input class="name-input" id="name-${g}" data-name="${g}" maxlength="60" value="${esc(state.names[g])}" aria-label="项目名称">`:`<h3>${esc(state.names[g])}</h3>`}<p>${meta.description}</p></div><button class="icon-btn" data-rename="${g}" aria-label="修改${esc(state.names[g])}项目名">${icon('pencil')}</button></header><div class="proposal-body"><h4>目前了解到的情况</h4>${factHTML(d)}<div class="next-step"><h4>${icon('corner-down-right')}建议从这里继续</h4><p>${nextFor(g,d)}</p></div></div><footer class="proposal-footer"><span>${d.length} 份相关材料 · ${new Set(d.map(m=>m.source)).size} 个来源</span><button class="text-button" data-group-materials="${g}">查看材料${icon('arrow-right')}</button></footer></article>`;}).join('')}</section><aside class="understanding-aside"><h3>把理解变成工作</h3><p>采用后，项目会带上这份摘要、相关材料和建议的下一步。</p><div class="source-dots">${state.done.map(id=>`<span>${srcIcon(sources.find(s=>s.id===id))}</span>`).join('')}</div><div class="aside-line">${icon('scan-text')}<strong>每个判断，都能回到原文</strong>点正文旁的来源编号，查看它依据了什么。</div><div class="aside-line">${icon('pencil-line')}<strong>你可以改写这份理解</strong>建议不会自动成为正式目标。进入项目后，摘要也可以继续编辑。</div></aside></div><div class="review-actionbar"><p>已选 ${gs.filter(g=>state.adopt.includes(g)).length} 个项目建议</p><div class="actions"><button class="btn quiet" data-action="save-draft">先保存整理稿</button><button class="btn primary" data-action="adopt" ${!gs.some(g=>state.adopt.includes(g))?'disabled':''}>${state.importTarget?'带入当前项目':'建立项目并开始'}${icon('arrow-right')}</button></div></div></main>`;}
function currentProject(){return state.projects.find(p=>p.id===state.projectId);}
function projectView(){const p=currentProject();if(!p){state.phase='sources';return sourcesView();}const docs=p.docs.map(byId).filter(Boolean),view=state.projectView;const next=docs.length?nextFor(p.group,docs):'写下一件想做的事，或带入已有材料。';const mobile=`<div class="mobile-nav">${[['overview','概览'],['materials','资料'],['goals','目标']].map(([v,n])=>`<button class="btn small ${view===v?'secondary':'quiet'}" data-view="${v}">${n}</button>`).join('')}<button class="btn small quiet" data-action="new-project" aria-label="新建项目">${icon('plus')}</button></div>`;let body='';if(view==='materials'){body=`<h1>项目资料</h1><p class="document-meta">${docs.length} 份固定材料 · 保留原始来源</p>${docs.length?materialList(docs):`<div class="journal-empty"><p>带入已有文件或工作往来，开始整理这个项目。</p><button class="btn primary" data-action="add-materials">带入材料</button></div>`}`;}else if(view==='goals'){body=`<h1>目标</h1>${p.goals?.length?`<section class="document-section">${p.goals.map(g=>`<div class="task-row">${icon('circle-dot')}<span>${esc(g)}</span></div>`).join('')}</section>`:`<div class="journal-empty">${icon('flag')}<h2>准备好时，再定一个目标</h2><p>整理建议已经保留在概览里。你可以决定哪些需要正式推进。</p></div>`}<button class="btn secondary" data-action="new-goal">${icon('plus')}新建目标</button>`;}else{body=`<h1>${esc(p.title)}</h1><div class="document-meta"><span>${icon('file-text')}工作摘要</span><span>${docs.length?'依据 '+docs.length+' 份材料整理':'空白项目'}</span><span data-save-status>已保存到演示项目</span></div>${!p.welcomeDismissed?`<div class="welcome-note">${icon('check-circle-2')}<span>${docs.length?'项目已经准备好。摘要和来源在这里，你可以从下一步继续。':'项目已创建。可以直接写摘要，也可以带入已有材料。'}</span><button class="icon-btn" data-action="dismiss-welcome" aria-label="关闭项目提示">${icon('x')}</button></div>`:''}<section class="document-section"><h2>背景与当前进展</h2>${editingSummary?`<textarea id="summary-editor" class="doc-editor" aria-label="编辑工作摘要">${esc(p.userSummary??factsFor(docs).map(f=>f.text).join('\n\n'))}</textarea><div class="editor-actions"><button class="btn quiet small" data-action="cancel-edit">取消</button><button class="btn primary small" data-action="save-summary">保存摘要</button></div>`:p.userSummary?`<p style="white-space:pre-wrap">${esc(p.userSummary)}</p>`:docs.length?factHTML(docs):'<p>还没有摘要，写下这个项目的背景或想法。</p>'}</section><section class="document-section"><h2>接下来可以做</h2><label class="task-row ${state.checks.includes(p.id)?'completed':''}"><input class="check" type="checkbox" data-task="${p.id}" ${state.checks.includes(p.id)?'checked':''}><span>${next}<small>整理建议 · 尚未创建为目标</small></span></label></section><section class="document-section"><h2>相关材料</h2>${docs.length?materialList(docs.slice(0,3)):''}<button class="text-button" ${docs.length?'data-view="materials"':'data-action="add-materials"'}>${docs.length?'查看全部 '+docs.length+' 份材料':'带入材料'}${icon('arrow-right')}</button></section>`;}return `<main class="project-shell animate-content"><aside class="sidebar"><div class="project-identity"><span class="project-symbol">${icon(p.group?groups[p.group].icon:'folder')}</span><h2>${esc(p.title)}</h2><small>本机项目 · 演示</small></div><nav aria-label="项目导航">${[['overview','house','概览'],['document','file-text','文档'],['materials','library','资料'],['goals','flag','目标']].map(([v,i,n])=>`<button class="nav-item ${view===v?'current':''}" data-view="${v}">${icon(i)}${n}${v==='materials'?'<span class="count">'+docs.length+'</span>':''}</button>`).join('')}</nav><div class="sidebar-section"><p>其他项目</p>${state.projects.filter(o=>o.id!==p.id).map(o=>`<button class="nav-item" data-project="${o.id}">${icon('folder')}<span>${esc(o.title)}</span></button>`).join('')}<button class="nav-item" data-action="new-project">${icon('plus')}新建项目</button></div><div class="sidebar-footer"><button class="nav-item" data-action="show-sources">${icon('plug')}已带入的来源</button></div></aside><div class="workspace-main"><header class="workspace-top"><div class="breadcrumbs">${icon('folder')}<button class="project-switch" data-action="switch-project" aria-label="切换项目，当前${esc(p.title)}">${esc(p.title)}${icon('chevrons-up-down')}</button>${icon('chevron-right')}<span>${{overview:'概览',document:'文档',materials:'资料',goals:'目标'}[view]}</span></div><button class="btn small quiet" data-action="${view==='overview'||view==='document'?'edit-summary':'new-project'}">${icon(view==='overview'||view==='document'?'pencil':'plus')}${view==='overview'||view==='document'?'编辑摘要':'新建项目'}</button></header><article class="workspace-document">${mobile}${body}</article></div></main>`;}
function materialList(docs){return docs.map(m=>`<button class="material-row" data-cite="${m.id}">${icon(m.kind==='邮件'?'mail':m.kind==='聊天'?'messages-square':m.kind==='网页'?'globe-2':'file-text')}<span><strong>${esc(m.title)}</strong><small>${esc(m.kind)} · ${esc(m.date)}</small></span>${icon('arrow-up-right')}</button>`).join('');}
function render(focusId){app.innerHTML=header()+(state.phase==='reading'?readingView():state.phase==='review'?reviewView():state.phase==='project'?projectView():sourcesView());lucide.createIcons({attrs:{'stroke-width':1.65}});const all=document.getElementById('select-all');if(all)all.indeterminate=state.selected.length>0&&state.selected.length<sources.length;if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});persist();}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('toast-visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('toast-visible'),3000);}
function openModal(title,body,footer=''){if(!modal.open)opener=document.activeElement;modal.innerHTML=`<header class="modal-header"><h2>${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="关闭">${icon('x')}</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}`;lucide.createIcons();modal.showModal();}
function closeModal(){modal.close();opener?.focus?.({preventScroll:true});}
modal.addEventListener('click',e=>{if(e.target===modal){const b=modal.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)closeModal();}});
function showCitation(id){const m=byId(id);if(!m)return;openModal('查看来源',`<h3 class="modal-source-title">${esc(m.title)}</h3><div class="source-origin"><strong>${esc(m.path)}</strong>${esc(m.kind)} · ${m.date} · 本次读取的内容快照</div><p class="source-body">${esc(m.body)}</p><p class="source-note">演示材料 · 总结依据此处正文，不会修改原文。</p>`,`<button class="btn secondary" data-action="close-modal">返回工作内容</button>`);}
function start(){if(!state.selected.length)return;clearTimeout(timer);state.phase='reading';state.done=[];state.skipped=[];state.failed=[];state.active=null;state.lastSelected=[...state.selected];render();window.scrollTo(0,0);schedule();}
function schedule(){clearTimeout(timer);if(state.phase!=='reading')return;const next=picked().find(s=>available(s)&&!state.done.includes(s.id)&&!state.skipped.includes(s.id));if(next){state.active=next.id;render();timer=setTimeout(()=>{if(state.phase!=='reading')return;state.done.push(next.id);state.active=null;render();schedule();},1300);return;}state.active=null;render();if(picked().every(s=>state.done.includes(s.id)||state.skipped.includes(s.id)))timer=setTimeout(()=>finish(),950);}
function finish(){clearTimeout(timer);state.active=null;state.skipped=[...new Set([...state.skipped,...state.selected.filter(id=>!state.done.includes(id))])];state.phase='review';state.adopt=resultGroups();render();window.scrollTo(0,0);}
function newProject(){openModal('新建项目',`<p>从已有工作开始，让项目带着内容就绪。</p><button class="choice-row" data-action="new-from-materials">${icon('folder-input','blue')}<span><strong>从已有材料开始</strong><small>勾选来源，自动整理摘要与项目建议</small></span>${icon('arrow-right')}</button><button class="choice-row" data-action="new-blank-form">${icon('file-plus-2')}<span><strong>空白开始</strong><small>给项目取个名字，随后再补充内容</small></span>${icon('arrow-right')}</button>`);}
function beginSources(target=null){closeModal();state.importTarget=target;clearTimeout(timer);state.returnProjectId=state.projectId;state.newProject=state.projects.length>0;state.phase='sources';state.selected=[];state.expanded=null;render();window.scrollTo(0,0);}
function blankForm(){if(modal.open)closeModal();openModal('新建空白项目',`<p>把同一件工作的内容放在一起。</p><form id="blank-form"><label for="blank-name">项目名称</label><input id="blank-name" class="field" name="name" maxlength="60" required placeholder="例如：秋季内容计划" autocomplete="off"><p id="blank-error" class="inline-error" hidden></p></form>`,`<button class="btn quiet" data-action="close-modal">取消</button><button class="btn primary" type="submit" form="blank-form">创建项目</button>`);document.getElementById('blank-name').focus();}
function adopt(){const gs=resultGroups().filter(g=>state.adopt.includes(g));if(!gs.length)return;if(state.importTarget){const p=state.projects.find(p=>p.id===state.importTarget);if(p){p.docs=[...new Set([...p.docs,...readMaterials().filter(m=>gs.includes(m.group)).map(m=>m.id)])];p.group=gs.length===1?gs[0]:null;p.welcomeDismissed=false;state.projectId=p.id;state.projectView='overview';state.phase='project';state.importTarget=null;state.newProject=false;render();window.scrollTo(0,0);toast('所选摘要与材料已带入当前演示项目');return;}}const newIds=[];for(const g of gs){const id='project-'+g+'-'+Date.now();state.projects.push({id,group:g,title:state.names[g].trim()||groups[g].title,docs:readMaterials().filter(m=>m.group===g).map(m=>m.id),goals:[]});newIds.push(id);}state.projectId=newIds[0];state.projectView='overview';state.phase='project';state.newProject=false;render();window.scrollTo(0,0);toast(`已建立 ${gs.length} 个演示项目，摘要和材料已带入`);}
app.addEventListener('change',e=>{const el=e.target;if(el.id==='select-all'){state.selected=el.checked?sources.map(s=>s.id):[];render(el.id);}else if(el.dataset.select){state.selected=el.checked?[...new Set([...state.selected,el.dataset.select])]:state.selected.filter(id=>id!==el.dataset.select);render(el.id);}else if(el.hasAttribute('data-days')){state.days=Number(el.value);render(el.id);}else if(el.dataset.range){state.scope[el.dataset.range]=el.value;render(el.id);}else if(el.dataset.adopt){state.adopt=el.checked?[...new Set([...state.adopt,el.dataset.adopt])]:state.adopt.filter(g=>g!==el.dataset.adopt);render(el.id);}else if(el.dataset.task){state.checks=el.checked?[...new Set([...state.checks,el.dataset.task])]:state.checks.filter(id=>id!==el.dataset.task);render();}});
app.addEventListener('input',e=>{if(e.target.dataset.name){state.names[e.target.dataset.name]=e.target.value;persist();}});
app.addEventListener('keydown',e=>{if(e.target.dataset.name&&e.key==='Enter'){e.preventDefault();editingName=null;render();}});
document.addEventListener('submit',e=>{if(e.target.id==='blank-form'){e.preventDefault();const title=document.getElementById('blank-name').value.trim();if(!title){const el=document.getElementById('blank-error');el.textContent='给项目取个名字，就可以开始。';el.hidden=false;return;}const p={id:'blank-'+Date.now(),title,docs:[],group:null,goals:[]};state.projects.push(p);state.projectId=p.id;state.projectView='overview';state.phase='project';state.newProject=false;closeModal();render();window.scrollTo(0,0);}else if(e.target.id==='goal-form'){e.preventDefault();const title=document.getElementById('goal-name').value.trim();if(!title)return;const p=currentProject();p.goals??=[];p.goals.push(title);closeModal();render();toast('目标已保存到演示项目');}});
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b||b.disabled)return;const d=b.dataset;
 if(d.scope){state.expanded=state.expanded===d.scope?null:d.scope;render(b.id);return;}
 if(d.connect){connecting=d.connect;render();await new Promise(r=>setTimeout(r,650));if(!['reading','sources'].includes(state.phase)){connecting=null;return;}state.connected=[...new Set([...state.connected,d.connect])];state.failed=state.failed.filter(id=>id!==d.connect);connecting=null;render();if(state.phase==='reading'&&!state.active)schedule();return;}
 if(d.skip){state.skipped=[...new Set([...state.skipped,d.skip])];state.failed=state.failed.filter(id=>id!==d.skip);render();if(!state.active)schedule();return;}
 if(d.fail){state.failed=[...new Set([...state.failed,d.fail])];render();return;}
 if(d.cite){showCitation(d.cite);return;}
 if(d.rename){editingName=d.rename;render();document.getElementById('name-'+d.rename)?.select();return;}
 if(d.groupMaterials){openModal('相关材料',`<p>这些材料共同构成了这份项目建议。</p>${materialList(readMaterials().filter(m=>m.group===d.groupMaterials))}`);return;}
 if(d.view){editingSummary=false;state.projectView=d.view;render();return;}
 if(d.project){if(modal.open)closeModal();state.projectId=d.project;state.projectView='overview';editingSummary=false;render();return;}
 const action=d.action;if(!action)return;e.preventDefault();
 if(action==='close-modal'){closeModal();return;}
 if(action==='theme'){const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;localStorage.setItem('molis-onboarding-demo-theme',theme);render();return;}
 if(action==='reset'){openModal('重新体验这段流程',`<p>清除这份原型的演示进度，回到来源清单。真实项目和账号不会受影响。</p>`,`<button class="btn quiet" data-action="close-modal">取消</button><button class="btn primary" data-action="confirm-reset">重新开始</button>`);return;}
 if(action==='confirm-reset'){closeModal();clearTimeout(timer);state=initialState();editingName=null;editingSummary=false;connecting=null;render();window.scrollTo(0,0);return;}
 if(action==='home'){if(state.projects.length){state.phase='project';state.projectId=state.projectId||state.projects[0].id;}else{clearTimeout(timer);state.phase='sources';}render();return;}
 if(action==='start'){start();return;}
 if(action==='privacy'){openModal('本次读取与整理',`<p>勾选表示选择这一行显示的范围。全选会保留你已经调整的范围。</p><div class="source-origin"><strong>只做本次整理</strong>不自动持续同步，不修改原文件，不回复邮件或消息。</div><p>正式产品会展示实际使用的模型服务，并说明所选正文将发送到哪里。</p><p class="source-note">当前为交互原型：全部来源与模型均为演示，不读取你的文件或账号。</p>`,`<button class="btn primary" data-action="close-modal">知道了</button>`);return;}
 if(action==='finish-partial'){finish();return;}
 if(action==='back-sources'){state.phase='sources';state.expanded=null;render();window.scrollTo(0,0);return;}
 if(action==='save-draft'){persist();toast('整理稿已保留，重新打开原型可以继续');return;}
 if(action==='adopt'){editingName=null;adopt();return;}
 if(action==='switch-project'){openModal('切换项目',state.projects.map(p=>`<button class="choice-row" data-project="${p.id}">${icon(p.group?groups[p.group].icon:'folder')}<span><strong>${esc(p.title)}</strong><small>${p.docs.length} 份材料${p.id===state.projectId?' · 当前项目':''}</small></span>${icon(p.id===state.projectId?'check':'arrow-right')}</button>`).join(''));return;}
 if(action==='new-project'){newProject();return;}
 if(action==='new-from-materials'||action==='add-materials'){if(!modal.open)opener=b;beginSources(action==='add-materials'?state.projectId:null);return;}
 if(action==='new-blank-form'){blankForm();return;}
 if(action==='back-project'){clearTimeout(timer);state.phase='project';state.projectId=state.returnProjectId||state.projects[0]?.id;render();return;}
 if(action==='edit-summary'){editingSummary=true;state.projectView='overview';render();document.getElementById('summary-editor')?.focus();return;}
 if(action==='cancel-edit'){editingSummary=false;render();return;}
 if(action==='save-summary'){currentProject().userSummary=document.getElementById('summary-editor').value;editingSummary=false;render();toast('摘要已保存');return;}
 if(action==='dismiss-welcome'){currentProject().welcomeDismissed=true;render();return;}
 if(action==='show-sources'){const docs=currentProject().docs.map(byId);const ids=[...new Set(docs.map(m=>m.source))];openModal('已带入的来源',ids.length?ids.map(id=>{const s=sources.find(x=>x.id===id);return `<div class="receipt"><span class="source-icon ${s.tone}">${srcIcon(s)}</span><div class="receipt-copy">${s.name}<p>${docs.filter(m=>m.source===id).length} 份材料 · 本次快照</p></div>${icon('check','green')}</div>`;}).join(''):'<p>这个项目还没有导入材料。</p>');return;}
 if(action==='new-goal'){openModal('新建目标',`<p>选择一件你想正式推进的事。</p><form id="goal-form"><label for="goal-name">目标名称</label><input id="goal-name" class="field" maxlength="120" required placeholder="例如：完成发布物料核对"></form>`,`<button class="btn quiet" data-action="close-modal">取消</button><button class="btn primary" type="submit" form="goal-form">保存目标</button>`);document.getElementById('goal-name').focus();}
});
render();if(state.phase==='reading')schedule();
